import pandapower as pp
import pandapower.networks as pn
from pandapower.estimation import estimate
STD_V, STD_P, STD_Q = 0.005, 1.0, 1.0
net = pn.case14()
pp.runpp(net)
tid = int(net.trafo.index[(net.trafo.hv_bus == 4 - 1) &
                          (net.trafo.lv_bus == 9 - 1)][0])
shunt_p, shunt_q = {}, {}
for si in net.shunt.index:
    b = int(net.shunt.bus.at[si])
    shunt_p[b] = shunt_p.get(b, 0.0) + float(net.res_shunt.p_mw.at[si])
    shunt_q[b] = shunt_q.get(b, 0.0) + float(net.res_shunt.q_mvar.at[si])
for b in net.bus.index:
    pp.create_measurement(net, 'v', 'bus', float(net.res_bus.vm_pu.at[b]),
                          STD_V, element=int(b))
for b in net.bus.index:
    p = float(net.res_bus.p_mw.at[b]) - shunt_p.get(int(b), 0.0)
    q = float(net.res_bus.q_mvar.at[b]) - shunt_q.get(int(b), 0.0)
    pp.create_measurement(net, 'p', 'bus', p, STD_P, element=int(b))
    pp.create_measurement(net, 'q', 'bus', q, STD_Q, element=int(b))
for li in net.line.index:
    pp.create_measurement(net, 'p', 'line', float(net.res_line.p_from_mw.at[li]),
                          STD_P, element=int(li), side='from')
    pp.create_measurement(net, 'q', 'line', float(net.res_line.q_from_mvar.at[li]),
                          STD_Q, element=int(li), side='from')
for ti in net.trafo.index:
    p = float(net.res_trafo.p_hv_mw.at[ti]) + (20.0 if int(ti) == tid else 0.0)
    pp.create_measurement(net, 'p', 'trafo', p, STD_P, element=int(ti), side='hv')
    pp.create_measurement(net, 'q', 'trafo', float(net.res_trafo.q_hv_mvar.at[ti]),
                          STD_Q, element=int(ti), side='hv')
estimate(net, init='flat')

def estimated(row):
    mt = row['measurement_type']
    et = row['element_type']
    e = int(row['element'])
    if et == 'bus':
        if mt == 'v':
            return float(net.res_bus_est.vm_pu.at[e])
        vm = float(net.res_bus_est.vm_pu.at[e])
        sp = sum(float(net.shunt.p_mw.at[s]) * vm ** 2 for s in net.shunt.index
                 if int(net.shunt.bus.at[s]) == e)
        sq = sum(float(net.shunt.q_mvar.at[s]) * vm ** 2 for s in net.shunt.index
                 if int(net.shunt.bus.at[s]) == e)
        if mt == 'p':
            return float(net.res_bus_est.p_mw.at[e]) - sp
        return float(net.res_bus_est.q_mvar.at[e]) - sq
    if et == 'line':
        if mt == 'p':
            return float(net.res_line_est.p_from_mw.at[e])
        return float(net.res_line_est.q_from_mvar.at[e])
    if mt == 'p':
        return float(net.res_trafo_est.p_hv_mw.at[e])
    return float(net.res_trafo_est.q_hv_mvar.at[e])

scores = {int(mi): abs(float(row['value']) - estimated(row)) / float(row['std_dev'])
          for mi, row in net.measurement.iterrows()}
drop = max(scores, key=lambda k: (scores[k], -k))
net.measurement = net.measurement.drop(index=drop)
estimate(net, init='flat')
angle = float(net.res_bus_est.va_degree.at[14 - 1]) - float(net.res_bus_est.va_degree.at[1 - 1])
print(round(angle, 6))
